import React from 'react';
import { Link } from 'react-scroll'; // Import Link from react-scroll
import resume from '../../assets/images/resume.jpg'; // Adjust the import path as needed

const Resume = () => {
  return (
    <div id="resume" className="section">
      <h1>Resume</h1>
      <img src={resume} alt="Resume" className="resume-image" />
      <a href="/Resume.pdf" download="Tanaya_Siddiqui_Resume.pdf" className="download-link">
        Download CV
      </a>
    </div>
  );
};

export default Resume;
